package cn.zhuatech.lms.controller; import cn.zhuatech.lms.common.ApiResponse; import cn.zhuatech.lms.dto.LmsDto.*; import cn.zhuatech.lms.service.LmsService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/shopfloor") @PreAuthorize("hasAnyRole('LEARNER','ADMIN')") public class LearnerController {private final LmsService service;public LearnerController(LmsService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.shopfloorDashboard());}@PostMapping("/work-orders/{id}/reports") public ApiResponse<ReportResult> report(@PathVariable Long id,@Valid @RequestBody ReportRequest request){return ApiResponse.ok("反馈提交成功",service.report(id,request));}}
